from urllib.parse import quote_plus as _day006_quote
_day006_terms = ('ACL', 'API', 'cgroups', 'chgrp', 'chmod', 'chown', 'Cloud Logging', 'Cloud Run', 'Compute Engine', 'copy-on-write', 'CPU', 'EACCES', 'Effective User ID', 'EGID', 'EUID', 'execve', 'Exit Status', 'file descriptor', 'File Descriptors', 'fork', 'FSGID', 'FSUID', 'GID', 'Group', 'I/O Redirection', 'IAM', 'idempotency', 'journalctl', 'Kernel Space', 'Linux permissions', 'Mode Bits', 'namespaces', 'Ops Agent', 'OS Login', 'Other', 'Owner', 'PID', 'pipefail', 'Pipelines', 'POSIX', 'Process', 'Process ID', 'Process supervision', 'procfs', 'SIGKILL', 'Signals', 'SIGPIPE', 'SIGTERM', 'sudo', 'Supplementary Groups', 'System Calls', 'systemd', 'systemd_journald', 'term1', 'term2', 'UID', 'Unit Files', 'User Space', 'VFS', 'Virtual File System')
def _day006_discovery(_content):
    _pattern = re.compile(r'(?<!\w)(?:' + '|'.join(re.escape(t) for t in sorted(_day006_terms, key=len, reverse=True)) + r')(?!\w)', re.I)
    _out, _stack, _used = [], [], set()
    _skip = {'h1','h2','h3','h4','h5','h6','kbd','code','samp','pre','figcaption','a','svg','title','desc','script','style'}
    for _piece in re.split(r'(<[^>]+>)', _content):
        if _piece.startswith('<'):
            _m = re.match(r'<(/?)([\w:-]+)', _piece)
            if _m:
                _closing, _tag = _m.groups()
                _tag = _tag.lower()
                if not _closing and _tag in ('h4','article'):
                    _used = set()
                if _closing:
                    _positions = [i for i,(t,_) in enumerate(_stack) if t == _tag]
                    if _positions:
                        _stack = _stack[:_positions[-1]]
                elif not _piece.endswith('/>') and _tag not in {'img','br','hr','input','image','meta','link'}:
                    _stack.append((_tag, _tag == 'strong' and bool(re.search(r'class=["\']keyword["\']', _piece))))
            _out.append(_piece)
            continue
        if any(t in _skip for t,_ in _stack):
            _out.append(_piece)
            continue
        _force = any(k for _,k in _stack)
        def _replace(_match):
            _value = _match.group()
            if _value.casefold() in _used and not _force:
                return _value
            _used.update(t.casefold() for t in _day006_terms if re.search(r'(?<!\w)' + re.escape(t) + r'(?!\w)', _value, re.I))
            return '<a href="http://www.google.com/search?q=' + _day006_quote(_value) + '" rel="noopener" target="_blank">' + _value + '</a>'
        _out.append(_pattern.sub(_replace, _piece))
    return ''.join(_out)
for _topic in DATA['topics']:
    def _day006_bullet(_match):
        _body = _match.group(1)
        _label = re.match(r'<strong class="side-heading">([^<]+)</strong>', _body)
        return '<ul><li>' + _body + '</li></ul>' if _label and _label.group(1).strip() not in {'Subtopics in this discussion:', 'Where it sits:', 'Linked subtopics:', 'Problem preview:', 'Evidence limit:', 'Why today:'} else _match.group()
    _topic['technical'] = _day006_discovery(re.sub(r'<p>(.*?)</p>', _day006_bullet, _topic['technical'], flags=re.S))
    if 'Keyword searches:' not in _topic['technical']:
        _searches = [t for t in _day006_terms if re.search(r'(?<!\w)' + re.escape(t) + r'(?!\w)', re.sub(r'<[^>]+>', ' ', _topic['technical']), re.I)]
        _topic['technical'] += '<div><strong class="side-heading">Keyword searches:</strong></div><ul>' + ''.join('<li><a href="http://www.google.com/search?q=' + _day006_quote(t) + '" rel="noopener" target="_blank">' + t + '</a> — discovery aid</li>' for t in _searches) + '</ul>'

